using FMODUnity;
using LittleLeo;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AtrociousDecimatorAnimationData", menuName = "Data/Animation/AtrociousDecimatorAnimationData")]
public class AtrociousDecimatorAnimationData : CustomAnimationData
{
	[Header("After Vanish Animation")]
	[SerializeField]
	private float afterVanishAnimationMixDuration = 1f;

	[Header("References")]
	[SerializeField]
	private CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	private HatchingChrysalisEffect hatchingChrysalisEffect;

	[SerializeField]
	private EventReference cocoonAttack;

	public override AnimationType GetCustomAttackAnimationType(SpriteControl spriteControl, EnemySFXData enemySFXData)
	{
		if (currentCorruptedAnimals.activeCorruptedAnimals.First().GetComponent<UnitEffects>().IsEffectActive(hatchingChrysalisEffect, activateFeedback: false))
		{
			ReferenceSingleton<SFXHandler>.Instance.PlaySFX(cocoonAttack);
			return AnimationType.Attack1;
		}
		if (enemySFXData.EnableEnemyAttackDelay)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enemySFXData.EnemyAttackDelay, delegate
			{
				enemySFXData.PlayEnemyAttackSFX();
			});
		}
		else
		{
			enemySFXData.PlayEnemyAttackSFX();
		}
		return AnimationType.Attack;
	}

	public override void AfterVanishAnimationLogic(SpriteControl spriteControl)
	{
		spriteControl.PlayAnimationForcedCoroutine(ReferenceSingleton<CoroutineHandler>.Instance, AnimationType.Skill1, AnimationChangeType.StayInTheNewAnimationNotLooping);
		spriteControl.SetMixDuration(afterVanishAnimationMixDuration);
	}
}
